prompt:
请只写一个文件 mc_gate_invariance.cpp（C++20，全局 main）。

【硬性约束】
1. 允许 include： "mc_gate_seed.h" "mc_gate_dgp.h" "mc_gate_streams.h" "mc_gate_adapter.h" "mc_gate_baselines.h"
   标准头：<cstdint> <cstddef> <cstdio> <string> <vector> <span>
2. 不要重新定义任何已存在的函数。main 第一行 `using namespace mc_gate;`。
3. 构建带 -Werror，零警告。只打印规定的行。

【已有接口（逐字）】
  std::string dataset_key(const char* comp, double S, int N, int T, double rho, const char* dist, double p, int ds);
  std::uint64_t seed_of(const std::string& key, int rep, int batch, const char* stream, std::uint64_t run_seed);
  ReturnMatrix generate_with_kappa(Family, Composition, int T, int N, double rho, double S,
                                   std::uint64_t seed, int kappa);
  ReturnMatrix hold_path(Family fam, int T, int N_hold, double rho,
                         const std::string& dataset_key, int rep, int batch, std::uint64_t run_seed);
  WindowStats make_window_stats(const ResearchWindow&, bool abstain=false);
  Decision decide_from_stats(const WindowStats&, const RuleConfig&);
  struct RuleConfig { GateMode mode; double q; double alpha; };

【参数】
T=100, N=126, rho=0.30, S=50.0, Family::T5, Composition::OneGood, kappa=7,
run_seed=20261027ULL, REPS=10
key = dataset_key("one_good", 50.0, 126, 100, 0.30, "t5", 50.4, 0)

【A 部分：AC-17 置换不变性】
对 rep = 0..9：
    s = seed_of(key, rep, 0, "ret", run_seed);
    ReturnMatrix m = generate_with_kappa(Family::T5, Composition::OneGood, T, N, 0.30, 50.0, s, 7);
    // 原序决策（m.r 已是 trial-major 连续数组，直接取 span，没有 m.flat()）
    std::span<const double> sp0(m.r.data(), m.r.size());
    ResearchWindow w0{ sp0, (std::size_t)T, (std::size_t)N, 0 };
    Decision d0 = decide_from_stats(make_window_stats(w0,false), RuleConfig{ GateMode::Full, 0.05, 0.05 });
    // 反序：构造 m2，使 m2 的第 i 条 = m 的第 (T-1-i) 条
    std::vector<double> rev((std::size_t)T*(std::size_t)N);
    for (int i = 0; i < T; ++i) for (int t = 0; t < N; ++t)
        rev[(std::size_t)i*N+t] = m.at(T-1-i, t);
    std::span<const double> sp1(rev.data(), rev.size());
    ResearchWindow w1{ sp1, (std::size_t)T, (std::size_t)N, 0 };
    Decision d1 = decide_from_stats(make_window_stats(w1,false), RuleConfig{ GateMode::Full, 0.05, 0.05 });
    // 判据：原序选中下标应为 7；反序后下标应为 T-1-7 = 92
    long long i0 = (long long)d0.index, i1 = (long long)d1.index;
    int ok = (d0.selected && d1.selected && i0 == 7 && i1 == (T-1-7)) ? 1 : 0;
    okA += ok;
    打印：PERM <rep> <i0> <i1> <ok>

【B 部分：AC-16 部署期路径不污染决策数据】
对 rep = 0..9：
    s = seed_of(key, rep, 0, "ret", run_seed);
    ReturnMatrix ma = generate_with_kappa(Family::T5, Composition::OneGood, T, N, 0.30, 50.0, s, 7);
    // 先生成 hold 路径（hold 子流，N_hold=2000），再重新生成同一份面板
    ReturnMatrix hp = hold_path(Family::T5, T, 2000, 0.30, key, rep, 0, run_seed);
    (void)hp;
    ReturnMatrix mb = generate_with_kappa(Family::T5, Composition::OneGood, T, N, 0.30, 50.0, s, 7);
    // 判据：两次面板逐字节相同
    int same = (ma.r.size() == mb.r.size() && std::memcmp(ma.r.data(), mb.r.data(),
                ma.r.size()*sizeof(double)) == 0) ? 1 : 0;
    okB += same;
    打印：HOLD <rep> <same> <ma.r.size()>

跑完后打印：
  AC17_OK <okA>/10
  AC16_OK <okB>/10
  INVAR_DONE

【输出纪律】10 行 PERM + 10 行 HOLD + 2 行 OK + 1 行 INVAR_DONE。
